import { NextResponse } from 'next/server';

// Serves the sitemap index at /movies/sitemap.xml
// The 3 sub-sitemaps are at /movies/sitemap/0.xml, /1.xml, /2.xml
// (generated by app/movies/sitemap.ts via generateSitemaps)

const SITE_URL =
  process.env.NEXT_PUBLIC_SITE_URL || 'https://filmoxa.vercel.app';

export const revalidate = 604800; // 7 days

export async function GET() {
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <sitemap>
    <loc>${SITE_URL}/movies/sitemap/0.xml</loc>
  </sitemap>
  <sitemap>
    <loc>${SITE_URL}/movies/sitemap/1.xml</loc>
  </sitemap>
  <sitemap>
    <loc>${SITE_URL}/movies/sitemap/2.xml</loc>
  </sitemap>
</sitemapindex>`;

  return new NextResponse(xml, {
    status: 200,
    headers: {
      'Content-Type': 'application/xml; charset=utf-8',
      'Cache-Control': 'public, max-age=604800, s-maxage=604800, stale-while-revalidate=86400',
    },
  });
}
